def _collapse(shape, strides):
    """Merge adjacent contiguous dimensions, drop size-1 dims.

    Returns dims ordered innermost-first: dim 0 is the fastest-varying
    (least significant) index in the linear decomposition.
    """
    dims = [(int(sz), int(st)) for sz, st in zip(shape, strides)]
    dims = [(sz, st) for sz, st in dims if sz != 1]
    if not dims:
        return [(1, 0)]
    out = [dims[-1]]
    for sz, st in reversed(dims[:-1]):
        psz, pst = out[-1]
        if st == psz * pst:
            out[-1] = (sz * psz, pst)
        else:
            out.append((sz, st))
    return out


